import base64,hashlib,json
from pathlib import Path
root=Path(__file__).resolve().parents[2]; audit=root/'Examtopics/audit'
s=(root/'CCNA-App/app/src/main/assets/data/ccna_cards_data.js').read_text(encoding='utf-8');qs=json.loads(s[s.index('['):].strip().rstrip(';')); by={q['id']:q for q in qs}
fp=lambda q:hashlib.sha256(json.dumps(q,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()).hexdigest()
opts=lambda d:[dict(label=k,text=v) for k,v in d.items()]
fix={
911:dict(prompt='Refer to the exhibit. VLAN 72 is already the data access VLAN on Ethernet0/0, which connects a Cisco IP phone and PC. CDP is enabled globally and on the port. Which command sequence creates voice VLAN 73 named VoIP and assigns it to the phone port?',options=opts({'A':'vlan 73\n name VoIP\ninterface Ethernet0/0\n switchport voice vlan dot1p','B':'vlan 73\n name VoIP\ninterface Ethernet0/0\n switchport voice vlan 72','C':'vlan 73\n name VoIP\ninterface Ethernet0/0\n switchport mode trunk\n channel-group 73 mode active','D':'vlan 73\n name VoIP\ninterface Ethernet0/0\n switchport voice vlan 73'}),explanation='D。图中 Et0/0 已属数据 VLAN 72；创建 VLAN 73 并在接口配置 `switchport voice vlan 73`，支持的 Cisco 电话通过 CDP 获取语音 VLAN。A 使用优先级标记而非 VLAN 73；B 指定 VLAN 72；C 将终端端口改为 trunk 并尝试聚合，未完成要求。语音 CoS 信任、QoS 和电话型号需按部署单独验证。'),
912:dict(explanation='B。图中 `10.10.10.0/28` 的范围为 10.10.10.0–10.10.10.15，包含 .3；掩码为 255.255.255.240，且比同样匹配的 10.0.0.0/8 更长。A 的 10.10.0.0/22 仅覆盖第三字节 0–3；D 的 /32 只匹配 .1。假定图示路由有效，最长前缀选 B；以太网仅指定出接口的静态路由在实际网络中还需考虑下一跳解析。'),
913:dict(prompt='A 10BASE-T/100BASE-TX router port uses MDI (pins 1/2 transmit; 3/6 receive), and the switch port uses MDI-X (pins 1/2 receive; 3/6 transmit). Auto-MDIX is unavailable. Which cable connects them?',explanation='D。两端的收发引脚互补，直通线使路由器 1/2 接交换机 1/2、交换机 3/6 接路由器 3/6。A 交叉线适用于相同收发引脚布局；B 和 C 为控制台用途。不要仅凭设备名称推断所有端口引脚：题设明确限定传统 10/100 接口和无 Auto-MDIX。'),
914:dict(prompt='Which listed application protocol is commonly used by web-based REST APIs?',explanation='D。Web REST API 通常使用 HTTP 或通过 TLS 保护的 HTTPS，并通过 URI、方法与状态码进行交互。REST 是架构风格，并非规定所有 REST 系统只能使用 HTTP 的独立协议。SSH 通常承载远程终端等；STP 用于二层防环；SNMP 是另一种网络管理协议。GET、PUT、DELETE 定义为幂等方法，但服务端仍可能记录日志等副作用。'),
915:dict(prompt='On a Cisco AireOS WLC model supporting AP-manager interfaces and LAG, which interface type is limited to one when LAG is enabled?',explanation='D。Cisco AireOS 文档指出启用 LAG 时仅支持一个 AP-manager；关闭 LAG 时可在支持的平台按端口配置多个。管理接口默认可承担 AP-manager 功能，不意味着启用 LAG 后必须创建独立接口，也不能把此规则直接推广到所有控制器型号。service 和 virtual 是其他用途的接口；trunk 是链路模式。'),
916:dict(prompt='Refer to the exhibit. A network plan requires the PC mask to match the router LAN interface mask. Which displayed PC setting differs from that plan?',explanation='A。路由器接口为 10.2.2.1/27，计划掩码是 255.255.255.224；图中 PC 为 10.2.2.2/26（255.255.255.192），故应把子网掩码改成 /27 以符合计划。默认网关 .1 与路由器地址一致。重要的是 .1 和 .2 在 /26 与 /27 下均被视为本地地址，单凭掩码不一致不能证明图中访问互联网失败的根因；DNS、路由与服务连通性仍需检查。'),
917:dict(explanation='C。Syslog severity 标识消息严重度，0–7 共八级，数值越小越严重。Cisco 日志中 facility 描述生成消息的功能组件；B 错在声称有 16 个严重度级别。D 的默认转发与阈值依设备、版本及是否配置日志服务器而异，不能假定全部级别均发送。UDP 514 常见，但 Syslog 也有其他传输方式。'),
918:dict(prompt='A traditionally managed network has many devices requiring repeated, standardized configuration changes. Which approach most directly centralizes those repetitive management tasks and can reduce maintenance effort while improving consistency?',explanation='C。集中执行经过测试的模板、自动化配置及核验，可减少逐台重复操作并提高配置一致性；节省程度取决于规模和实施成本，自动化本身不能保证无故障。A 的自动监控可帮助提前发现问题，但题目侧重批量配置管理；B 增加人员不直接减少维护工作；D 的变更验证有价值但仅覆盖验证环节。'),
919:dict(prompt='An autonomous AP uses one SSID mapped to client VLAN 20; its management traffic uses VLAN 10. Both VLANs must traverse the same wired uplink, and VLAN 20 is 802.1Q tagged. Which switch-port mode supports this design?',explanation='A。题设明确要求一条链路承载管理 VLAN 10 与不同的客户端 VLAN 20，且 VLAN 20 打标签，故使用 802.1Q trunk 并匹配两端 native/允许 VLAN 配置。C 的普通 access 口只承载一个数据 VLAN；B 不是端口模式；D 是链路聚合，不是承载多个 VLAN 的必要条件。只有一个 SSID 或自主模式本身不必然要求 trunk：管理和客户端共用一个 VLAN 时，适用设备也可使用 access。'),
920:dict(prompt='Refer to the exhibit. On an AireOS WLC, User1 and User2 must be directed to a web login before normal network access. Before authentication, ordinary client IP traffic is blocked except DHCP and DNS, with no pre-auth ACL exceptions. Which WLAN configuration enables this behavior?',explanation='C。在 WLAN Security > Layer 3 启用 Web Policy 并选择 Authentication。A 将 Web 认证误放在二层；B 的 MAC 过滤不等同 Web 登录；D 的 AAA 服务器配置不是启用该策略的位置。Cisco 文档说明认证前普通 IP 流量默认仅放 DHCP/DNS，HTTP 请求可被拦截并重定向至门户；预认证 ACL 可以另行放行流量。认证后仍受网络策略约束，不代表所有流量无条件放行。')}
sources=['https://www.cisco.com/c/en/us/support/docs/switches/catalyst-4500-series-switches/69632-configuring-cat-ip-phone.html','https://www.cisco.com/c/en/us/td/docs/wireless/controller/8-10/config-guide/b_cg810/ports_and_interfaces.html','https://www.cisco.com/c/en/us/support/docs/wireless/5500-series-wireless-controllers/108501-webauth-tshoot.html']
reasons={911:'原B也配置voice VLAN 73，可能与D同时满足要求；重写干扰项并恢复CLI。',912:'核对路由图，限定路由有效并说明仅出接口解析条件。',913:'明确两端引脚及传统10/100约束，避免以设备类别绝对化。',914:'限定Web REST并纠正必须依赖HTTP的绝对说法。',915:'限定AireOS平台，说明管理接口可承担AP-manager。',916:'原题将掩码不一致误认为必然导致上网失败；改为匹配计划的可证实问题。',917:'修正默认日志阈值与传输方式的绝对说法。',918:'限定批量变更场景，避免监控也合理，并纠正自动化保证无错的说法。',919:'原题缺少多VLAN前提，补充具体VLAN并解释单VLAN可用access。',920:'明确认证前阶段和ACL例外，说明HTTP重定向及认证后策略。'}
cs=[];lines=['# Q911–Q920 逐题审查','', '逐题核对题干、所有选项、答案、解析、图片和CLI；未进行设备实测。','']
for n in range(911,921):
 q=by[n]; u=fix[n]; assert set(q['answer'])<={o['label'] for o in u.get('options',q['options'])}
 c=dict(id=n,original_qid=q['qid'],before_sha256=fp(q),reason=reasons[n],updates=u,original_fields={k:q[k] for k in u},review=dict(prompt='checked',options='checked',answer='checked and retained',explanation='checked and corrected',image='viewed' if q.get('image') else 'none',code_cli='checked',finding=reasons[n]))
 if q.get('image'):
  p=audit/'exhibits'/f'q{n}_agent.jpg';assert p.read_bytes()==base64.b64decode(q['image'].split(',',1)[1]);c['exhibit_path']=str(p.relative_to(audit));c['image_sha256']=hashlib.sha256(p.read_bytes()).hexdigest()
 cs.append(c);lines.append(f'- Q{n} ({q["qid"]})：{reasons[n]} 答案 {"/".join(q["answer"])} 保持；'+('原图已直接查看。' if q.get('image') else '无原图。'))
lines+=['','## 依据','']+[f'- {x}' for x in sources]
(audit/'agent-0911-0920.json').write_text(json.dumps(dict(scope='Q911–Q920',corrections=cs,sources=sources,limitations='未进行设备或网络实验'),ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
(audit/'agent-0911-0920.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
print('Q911–Q920 manifest and review written')
